function lpdmV2Browse(){const g=lpdmV2.find(x=>x[0]==="fragrance");return lpdmV2Page(g,null,false,true);}
const htmlResponse = (body) => new Response(body,{headers:{"content-type":"text/html; charset=utf-8","x-content-type-options":"nosniff","cache-control":"public, max-age=300"}});
export default {
  async fetch(request) {
    const rawPath = new URL(request.url).pathname;
    const pathname = rawPath.length > 1 && rawPath.endsWith("/") ? rawPath.slice(0,-1) : rawPath;
    if(pathname === "/health") return Response.json({status:"ok",service:"lpdm-web"});
    if(pathname === "/") return htmlResponse(lpdmV2Page(null,null));
    if(pathname === "/sitemap") return htmlResponse(lpdmV2Page(null,null,true));
    if(pathname === "/fragrance/browse") return htmlResponse(lpdmV2Browse());
    const v2Parts=pathname.split("/").filter(Boolean);
    const v2Group=lpdmV2.find(g=>g[0]===v2Parts[0]);
    if(v2Group && v2Parts.length<=2){
      if(v2Parts.length===1) return htmlResponse(lpdmV2Page(v2Group,null));
      const v2Item=v2Group[3].find(i=>i[0]===v2Parts[1]);
      if(v2Item) return htmlResponse(lpdmV2Page(v2Group,v2Item));
    }
    if(pathname==="/about") return Response.redirect(new URL("/about-v2",request.url).toString(),302);
    if(pathname==="/memorials") return Response.redirect(new URL("/fragrance",request.url).toString(),302);
    if(pathname==="/news") return Response.redirect(new URL("/events",request.url).toString(),302);
    if(pathname==="/support") return Response.redirect(new URL("/about-v2/partners",request.url).toString(),302);
    
    const parts=pathname.split("/").filter(Boolean);
    const group=siteSections.find(s=>s.slug===parts[0]);
    if(group&&parts.length<=2&&(!parts[1]||group.children.some(c=>c[0]===parts[1]))) return htmlResponse(sectionPage(group,parts[1]));

    if(pathname === memorialBase) return htmlResponse(memorialPage(""));
    const prefix = memorialBase + "/";
    if(pathname.startsWith(prefix)) {
      const slug = pathname.slice(prefix.length);
      const legacy={philosophy:"introduction",practice:"life",forest:"garden"};
      if(legacy[slug]) return Response.redirect(new URL(prefix+legacy[slug],request.url).toString(),302);
      if(memorialSections.some(s => s.slug === slug)) return htmlResponse(memorialPage(slug));
    }
    return new Response("페이지를 찾을 수 없습니다.",{status:404,headers:{"content-type":"text/plain; charset=utf-8"}});
  }
};
